// =============================================================================
// Mathematics — Word-based mathematics, slice 1 (Elementary)
// =============================================================================
// Darrell, 2026-09-15: "add Mathematics as a Tab... in that sliding sub-tab
// inside Learn"; and from the Little Learners directive the same day, "math
// that has the Word, totally Word based... the math of the Bible... qualitative
// and quantitative ways of math, like engineering." (DR-0433; the school is
// DR-0432.)
//
// SLICE 1 (this file, generated from scratch/math/gen.mjs so every quoted span
// is fetched verbatim from app/public/bible/kjv and never typed): counting and
// place value · adding and taking away · multiplying and sharing · parts and
// fractions · measure · shapes · time and cycles · qualitative and
// quantitative. Every number a lesson works with is a number the Word
// records, quoted whole with its reference beside it; the working is shown
// on the page; the check reads its choices aloud and can be redone as a game.
// Elementary register (Flesch-Kincaid held at or under 5.0 by the course gate,
// the top of US grades 1 to 5 — DR-0417 D3's age number).
//
// What this slice does NOT claim: the Word is not a mathematics textbook and
// is never made to say what it does not say. Where a measurement is a round
// measurement (the molten sea's ten across and thirty about), the lesson says
// so and teaches the true ratio beside it, rather than reading a formula into
// a description (DR-0076; DR-0098: teach what is written and stop).
// =============================================================================
import {
  progressSummaryFor, exportCurriculumMarkdownFor, resolveCohortGeneric,
} from './church-classes.js';

export const MATHEMATICS_PROPOSED_COHORT_START = null;
export const MATHEMATICS_CONFIRMED_COHORT = { startDate: null, confirmed: false };

export const MATHEMATICS_MODULES = [
  { id: 'mat1-count-and-place-value-the-numbers-he-recorded', title: 'Count and Place Value — Ones, Tens, Hundreds and Thousands from the Census', bigIdea: 'THE WORD COUNTS PEOPLE, YEARS AND STARS WITH REAL NUMBERS, AND MOSES SORTED A NATION INTO THOUSANDS, HUNDREDS, FIFTIES AND TENS, SO PLACE VALUE IS OLDER THAN ANY SCHOOL', anchor: { ref: 'Numbers 1:46; Exodus 18:21; Psalms 147:4', theme: 'KJV: "He telleth the number of the stars; he calleth them all by their names." (Psalms 147:4)' }, lesson: 'Numbers are how we say how many. The Word is full of them. Let us start with a very big one. Moses counted the men of Israel. Here is the total. "Even all they that were numbered were six hundred thousand and three thousand and five hundred and fifty." (Numbers 1:46) Six hundred thousand and three thousand and five hundred and fifty. Write it with digits. 603,550. Look at each place. The 6 is in the hundred thousands place. The 0 is in the ten thousands place. The 3 is in the thousands place. The 5 is in the hundreds place. The next 5 is in the tens place. The 0 is in the ones place. Each place is ten times bigger than the one to its right. Ten ones make a ten. Ten tens make a hundred. Ten hundreds make a thousand. That is place value. Now watch Moses use it. His father in law told him to sort the people into groups. "Moreover thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness; and place such over them, to be rulers of thousands, and rulers of hundreds, rulers of fifties, and rulers of tens:" (Exodus 18:21) Thousands, hundreds, fifties, tens. That is grouping by place. A ruler of ten had ten people. A ruler of a hundred had ten rulers of ten under him. A ruler of a thousand had ten rulers of a hundred. Count it. Ten times ten is one hundred. Write it. 10 x 10 = 100. Ten times one hundred is one thousand. Write it. 10 x 100 = 1,000. Moses built a whole nation on tens. Now a smaller number. Jacob went to Egypt with his family. "And the sons of Joseph, which were born him in Egypt, were two souls: all the souls of the house of Jacob, which came into Egypt, were threescore and ten." (Genesis 46:27) Threescore and ten. A score is twenty. Three scores is three twenties. Twenty, forty, sixty. Then ten more. Seventy. Write it. 70. A 7 in the tens place. A 0 in the ones place. Jesus used the same number. "After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come." (Luke 10:1) Seventy people, sent out two by two. How many pairs is that? Seventy split into twos is thirty five pairs. Now a number about years. Methuselah lived a very long time. "And all the days of Methuselah were nine hundred sixty and nine years: and he died." (Genesis 5:27) Nine hundred sixty and nine. Write it. 969. Nine hundreds. Six tens. Nine ones. Say it by place. Nine hundreds, six tens, nine ones. Now the biggest count of all. "He telleth the number of the stars; he calleth them all by their names." (Psalms 147:4) Yahweh counts the stars. Every one. And He names each one. No person can count that high. He can. And He counts you too. "But the very hairs of your head are all numbered." (Matthew 10:30) Even the hairs on your head have a number. Try it. Write these numbers with digits. Threescore and ten. Six hundred and three thousand five hundred and fifty. Nine hundred sixty and nine. Now say each digit\'s place out loud. Then count something in your house by tens. Put ten spoons in a pile. Then ten more. Two tens is twenty. That is how Moses counted a nation, and how you can count anything.', inApp: 'Write 603,550 and say the place of every digit. Then make piles of ten with spoons or blocks and count by tens to one hundred.', benefits: ['Place value from the census: ones, tens, hundreds, thousands, each ten times the last.', 'Moses sorted a nation by thousands, hundreds, fifties and tens: grouping is in the Word.', 'Scores and threescore and ten: old number words the child can now read.', 'He counts the stars and the hairs: counting has no top.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'In 603,550, which digit is in the thousands place?', options: ['6', '3', '5'], answer: 1, explain: 'Reading from the right: 0 ones, 5 tens, 5 hundreds, 3 thousands. The 3 is in the thousands place.' }, { q: 'How many ones make one ten?', options: ['Ten', 'Five', 'A hundred'], answer: 0, explain: 'Ten ones make a ten. Ten tens make a hundred. Each place is ten times the last.' }, { q: 'Threescore and ten is how many?', options: ['Thirty', 'Seventy', 'Sixty'], answer: 1, explain: 'A score is twenty. Three scores are sixty. Ten more is seventy.' }, { q: 'Moses sorted the people into thousands, hundreds, fifties and what?', options: ['Twos', 'Tens', 'Sevens'], answer: 1, explain: 'Exodus 18:21: rulers of thousands, of hundreds, of fifties, and of tens.' }, { q: 'How many rulers of ten stood under one ruler of a hundred?', options: ['Ten', 'Two', 'A hundred'], answer: 0, explain: 'Ten groups of ten make a hundred, so ten rulers of ten.' }, { q: 'Who counts the number of the stars?', options: ['Moses', 'Yahweh', 'Nobody'], answer: 1, explain: 'Psalms 147:4: He telleth the number of the stars and calleth them all by their names.' }] }, facilitator: { talkingPoints: ['Numbers 1:46: write 603,550 and name each place.', 'Exodus 18:21: thousands, hundreds, fifties, tens — grouping by place.', 'Genesis 46:27 and Luke 10:1: threescore and ten; seventy in pairs.', 'Genesis 5:27: 969 by hundreds, tens and ones.', 'Psalms 147:4; Matthew 10:30: He counts what no one else can.'], howToRun: 'No grown-up is needed: the app reads the lesson and the check aloud. If a grown-up is near: write 603,550 large on paper and let the learner touch each digit while saying its place; then build piles of ten and count by tens. Redo the check as a game (about 20 minutes).', discussionPrompts: ['Which place is ten times bigger than the tens place?', 'Why did Moses need rulers of ten before rulers of a thousand?', 'What is something in your house you could count by tens?'] } },
  { id: 'mat2-adding-and-taking-away-loaves-fishes-and-gideons-army', title: 'Adding and Taking Away — Loaves, Fishes, Baskets and Gideon’s Army', bigIdea: 'FIVE LOAVES AND TWO FISHES ARE SEVEN, TWELVE BASKETS ARE MORE THAN SEVEN, AND GIDEON’S ARMY WAS TAKEN AWAY FROM THIRTY-TWO THOUSAND TO THREE HUNDRED, SO THE WORD ADDS AND SUBTRACTS IN FRONT OF US', anchor: { ref: 'Matthew 14:17; Matthew 14:20; Judges 7:3; Judges 7:6', theme: 'KJV: "And they did all eat, and were filled: and they took up of the fragments that remained twelve baskets full." (Matthew 14:20)' }, lesson: 'Adding is putting together. Taking away is subtracting. The Word does both. First, adding. A crowd was hungry. The disciples looked at what they had. "And they say unto him, We have here but five loaves, and two fishes." (Matthew 14:17) Five loaves. Two fishes. Put them together. Five plus two. Count on from five. Six, seven. Five plus two equals seven. Write it. 5 + 2 = 7. Seven pieces of food. Then Jesus gave thanks and broke the bread. Everyone ate. Look what was left. "And they did all eat, and were filled: and they took up of the fragments that remained twelve baskets full." (Matthew 14:20) Twelve baskets. Compare. They started with seven pieces. They ended with twelve baskets full. Twelve is more than seven. How much more? Twelve take away seven. Count back from twelve. Eleven, ten, nine, eight, seven. That is five steps. Twelve minus seven equals five. Write it. 12 - 7 = 5. And how many people ate? "And they that had eaten were about five thousand men, beside women and children." (Matthew 14:21) Five thousand men, plus the women and children. The Word gives the count it has and says plainly what it did not count. That is honest counting. Now, taking away. Gideon had a big army. Yahweh said it was too big. So He told Gideon to send some home. "Now therefore go to, proclaim in the ears of the people, saying, Whosoever is fearful and afraid, let him return and depart early from mount Gilead. And there returned of the people twenty and two thousand; and there remained ten thousand." (Judges 7:3) Twenty two thousand went home. Ten thousand stayed. So how many did Gideon start with? Add them back. Twenty two thousand plus ten thousand. That is thirty two thousand. Write it. 22,000 + 10,000 = 32,000. Then Yahweh took away more. "And the number of them that lapped, putting their hand to their mouth, were three hundred men: but all the rest of the people bowed down upon their knees to drink water." (Judges 7:6) Three hundred stayed. How many were sent home this time? Ten thousand take away three hundred. 10,000 - 300 = 9,700. Nine thousand seven hundred went home. From thirty two thousand down to three hundred. Why? So everyone would know the win came from Yahweh, not from a big army. Here is one more taking away. A shepherd had a hundred sheep. "What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?" (Luke 15:4) One got lost. A hundred take away one. 100 - 1 = 99. Ninety nine were safe. But the shepherd went to find the one. In math, one is small. To the shepherd, that one was worth the walk. Try it. Use blocks. Put five in a row. Add two. Count them. Now put twelve in a row. Take seven away. Count what is left. Then try Gideon. Say thirty two thousand. Take away twenty two thousand. What is left? Ten thousand. Take away nine thousand seven hundred. What is left? Three hundred. You are doing the math the Word did.', inApp: 'With blocks or beans: show 5 + 2 = 7, then 12 - 7 = 5. Then say Gideon’s two subtractions out loud with the answers.', benefits: ['Adding from the loaves and fishes: 5 + 2 = 7, with counting on.', 'Comparing and subtracting: twelve baskets is five more than seven pieces.', 'Gideon’s army: subtraction with big numbers, and adding back to find the start.', 'The one lost sheep: what a number is worth is not only its size.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'Five loaves plus two fishes is how many pieces of food?', options: ['Seven', 'Five', 'Ten'], answer: 0, explain: 'Five plus two. Count on from five: six, seven. 5 + 2 = 7.' }, { q: 'Twelve baskets take away seven pieces is how many?', options: ['Three', 'Five', 'Nineteen'], answer: 1, explain: 'Count back from twelve seven times and you land on five. 12 - 7 = 5.' }, { q: 'Twenty two thousand went home and ten thousand stayed. How many did Gideon start with?', options: ['Twelve thousand', 'Thirty two thousand', 'Twenty thousand'], answer: 1, explain: 'Add them back together: 22,000 + 10,000 = 32,000.' }, { q: 'Ten thousand take away three hundred is how many?', options: ['Nine thousand seven hundred', 'Seven thousand', 'Nine thousand three hundred'], answer: 0, explain: '10,000 - 300 = 9,700. Those went home; three hundred stayed.' }, { q: 'A hundred sheep take away one lost sheep leaves how many?', options: ['Ninety', 'Ninety nine', 'A hundred and one'], answer: 1, explain: '100 - 1 = 99. Ninety nine were safe and the shepherd went for the one.' }, { q: 'Why did Yahweh make Gideon’s army smaller?', options: ['To lose the battle', 'So everyone would know the win came from Him', 'Because the men were tired'], answer: 1, explain: 'Judges 7 says the army was too many, lest Israel say their own hand saved them.' }] }, facilitator: { talkingPoints: ['Matthew 14:17, 20, 21: 5 + 2 = 7; 12 - 7 = 5; the honest count of five thousand men.', 'Judges 7:3, 6: 22,000 + 10,000 = 32,000; 10,000 - 300 = 9,700.', 'Luke 15:4: 100 - 1 = 99, and the worth of the one.'], howToRun: 'No grown-up is needed. If one is near: lay out five and two objects, join them, count; lay out twelve, remove seven, count. Write each number sentence as you go. Then say Gideon’s subtractions aloud together. Redo the check as a game (about 20 minutes).', discussionPrompts: ['How do you count on to add?', 'Which is bigger, twelve baskets or seven pieces, and by how much?', 'Why did the shepherd leave ninety nine to find one?'] } },
  { id: 'mat3-multiplying-and-sharing-thirtyfold-sixtyfold-hundredfold', title: 'Multiplying and Sharing — Thirtyfold, Seventy Times Seven, and Twelve Oxen for Six Wagons', bigIdea: 'THE SEED THAT BRINGS FORTH THIRTY, SIXTY AND A HUNDREDFOLD IS MULTIPLICATION, SEVENTY TIMES SEVEN IS FOUR HUNDRED AND NINETY, AND TWELVE OXEN SHARED AMONG SIX WAGONS IS DIVISION', anchor: { ref: 'Mark 4:20; Matthew 18:22; Numbers 7:3', theme: 'KJV: "And these are they which are sown on good ground; such as hear the word, and receive it, and bring forth fruit, some thirtyfold, some sixty, and some an hundred." (Mark 4:20)' }, lesson: 'Multiplying is adding the same number again and again. Sharing out is dividing. The Word does both. First, multiplying. Jesus told about seed in good ground. "And these are they which are sown on good ground; such as hear the word, and receive it, and bring forth fruit, some thirtyfold, some sixty, and some an hundred." (Mark 4:20) Thirtyfold means thirty times as much. Plant one seed, get thirty seeds. Plant one, get sixty. Plant one, get a hundred. Now plant two seeds at thirtyfold. Two times thirty. Thirty and thirty. Sixty. Write it. 2 x 30 = 60. Plant three seeds at thirtyfold. Thirty, sixty, ninety. 3 x 30 = 90. Plant two seeds at a hundredfold. A hundred and a hundred. 2 x 100 = 200. That is how a field grows. Now a famous one. Peter asked how many times to forgive. Seven? Jesus said more. "Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven." (Matthew 18:22) Seventy times seven. Let us work it. Seven times seven is forty nine. So seventy times seven is ten times that. Forty nine times ten. Move every digit one place to the left. Four hundred ninety. Write it. 70 x 7 = 490. Jesus did not mean stop at four hundred ninety. He meant keep forgiving. But the number is real, and you can work it. Here is another way to see multiplying. Jesus sat the crowd down in rows. "And they sat down in ranks, by hundreds, and by fifties." (Mark 6:40) Groups of a hundred and groups of fifty. Ten groups of a hundred is one thousand. 10 x 100 = 1,000. Twenty groups of fifty is also one thousand. 20 x 50 = 1,000. Same total, different groups. Now sharing, which is dividing. The princes brought gifts for the tabernacle. "And they brought their offering before the LORD, six covered wagons, and twelve oxen; a wagon for two of the princes, and for each one an ox: and they brought them before the tabernacle." (Numbers 7:3) Six wagons and twelve oxen. Share the oxen among the wagons. Twelve shared by six. Give each wagon one ox. That uses six. Give each wagon one more. That uses twelve. Each wagon has two oxen. Write it. 12 divided by 6 = 2. And check it by multiplying. 6 x 2 = 12. Yes. Dividing and multiplying undo each other. One more sharing. Seven loaves fed four thousand, and seven baskets were left. "And they did all eat, and were filled: and they took up of the broken meat that was left seven baskets full." (Matthew 15:37) Seven baskets shared among seven basket carriers is one each. 7 divided by 7 = 1. Any number shared by itself is one. Try it. Take twelve beans and six cups. Share them out one at a time. How many in each cup? Now take thirty beans. That is one seed at thirtyfold. Two seeds would be two piles of thirty. Count them together. Sixty. You just multiplied.', inApp: 'Share 12 beans among 6 cups and say the division sentence. Then build two piles of thirty and count the total to show 2 x 30 = 60.', benefits: ['Multiplying as repeated adding, from the seed that brings forth thirtyfold.', 'Seventy times seven worked out on the page: 490.', 'Groups of a hundred and groups of fifty: two ways to make a thousand.', 'Dividing as sharing, from twelve oxen and six wagons, and checked by multiplying.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'Two seeds at thirtyfold give how many?', options: ['Thirty two', 'Sixty', 'Ninety'], answer: 1, explain: 'Thirty and thirty is sixty. 2 x 30 = 60.' }, { q: 'Seventy times seven is how many?', options: ['Four hundred ninety', 'Seventy seven', 'Four hundred'], answer: 0, explain: 'Seven times seven is forty nine; ten times that is four hundred ninety.' }, { q: 'Twelve oxen shared among six wagons is how many oxen each?', options: ['Two', 'Six', 'Three'], answer: 0, explain: '12 divided by 6 = 2, and 6 x 2 = 12 checks it.' }, { q: 'How many groups of fifty make a thousand?', options: ['Ten', 'Twenty', 'Fifty'], answer: 1, explain: '20 x 50 = 1,000. Ten groups of a hundred also make a thousand.' }, { q: 'What undoes multiplying?', options: ['Adding', 'Dividing', 'Counting'], answer: 1, explain: 'Dividing and multiplying undo each other: 6 x 2 = 12 and 12 divided by 6 = 2.' }, { q: 'Seven baskets shared among seven carriers is how many each?', options: ['Seven', 'One', 'Zero'], answer: 1, explain: 'Any number shared by itself is one. 7 divided by 7 = 1.' }] }, facilitator: { talkingPoints: ['Mark 4:20: thirtyfold, sixtyfold, a hundredfold as multiplying.', 'Matthew 18:22: 70 x 7 = 490, and what Jesus meant by it.', 'Mark 6:40: 10 x 100 and 20 x 50, one thousand two ways.', 'Numbers 7:3: 12 divided by 6 = 2, checked by 6 x 2 = 12.', 'Matthew 15:37: seven shared by seven is one.'], howToRun: 'No grown-up is needed. If one is near: share beans into cups for the division, then build equal piles for the multiplication, writing each number sentence. Redo the check as a game (about 20 minutes).', discussionPrompts: ['How is multiplying like adding again and again?', 'Why did Jesus say seventy times seven instead of seven?', 'Show two different ways to make a thousand with groups.'] } },
  { id: 'mat4-parts-and-fractions-the-tenth-the-fifth-and-the-half', title: 'Parts and Fractions — the Tenth, the Fifth, the Half and the Double Portion', bigIdea: 'THE TITHE IS ONE TENTH, RESTITUTION ADDS A FIFTH, ZACCHAEUS GAVE HALF, THE FIRSTBORN RECEIVED A DOUBLE PORTION, AND AN OMER IS A TENTH OF AN EPHAH: THE WORD TEACHES FRACTIONS BY USING THEM', anchor: { ref: 'Leviticus 27:30; Leviticus 6:5; Luke 19:8; Exodus 16:36', theme: 'KJV: "Now an omer is the tenth part of an ephah." (Exodus 16:36)' }, lesson: 'A fraction is a part of a whole. The Word uses parts all the time. Start with the tenth. "And all the tithe of the land, whether of the seed of the land, or of the fruit of the tree, is the LORD’s: it is holy unto the LORD." (Leviticus 27:30) The tithe is a tenth. Cut a whole into ten equal parts. One part is one tenth. Write it. 1/10. If a farmer grew one hundred bags of grain, a tenth is ten bags. One hundred split into ten parts is ten each. If he grew fifty bags, a tenth is five bags. To find a tenth, share into ten. Now the fifth. If someone took what was not theirs, the Word says to give it back and add more. "Or all that about which he hath sworn falsely; he shall even restore it in the principal, and shall add the fifth part more thereto, and give it unto him to whom it appertaineth, in the day of his trespass offering." (Leviticus 6:5) The fifth part. Cut a whole into five equal parts. One part is one fifth. Write it. 1/5. Say a man took ten coins. He gives back the ten. Then he adds a fifth of ten. Ten shared into five is two. So he gives back twelve coins. Ten plus two. Joseph used the fifth too. "Let Pharaoh do this, and let him appoint officers over the land, and take up the fifth part of the land of Egypt in the seven plenteous years." (Genesis 41:34) A fifth of the harvest was saved each year. Out of every five bags, one went into the storehouse. That fifth fed Egypt when the famine came. Now the half. Zacchaeus met Jesus and changed. "And Zacchaeus stood, and said unto the Lord; Behold, Lord, the half of my goods I give to the poor; and if I have taken any thing from any man by false accusation, I restore him fourfold." (Luke 19:8) Half of his goods. Cut a whole into two equal parts. One part is one half. Write it. 1/2. If he had forty coins, half is twenty. Forty shared into two is twenty. And for anyone he cheated, he gave back fourfold. Four times. If he took three coins, he gave back twelve. 3 x 4 = 12. Now a bigger part. The firstborn son got a double portion. "But he shall acknowledge the son of the hated for the firstborn, by giving him a double portion of all that he hath: for he is the beginning of his strength; the right of the firstborn is his." (Deuteronomy 21:17) Double means two parts instead of one. If a father had three sons and four equal parts to give, the firstborn got two parts and the other two sons got one each. Two plus one plus one is four. Now measure with parts. The Word measures grain with an ephah and an omer. "Now an omer is the tenth part of an ephah." (Exodus 16:36) An omer is a tenth of an ephah. So ten omers make one ephah. Each person in the wilderness got one omer of manna a day. A family of five got five omers. That is five tenths of an ephah. Five tenths is the same as one half. Half an ephah for the family each day. Try it. Take ten coins. Move one to the side. That is a tenth. Now take ten again. Share them into five piles. One pile is a fifth. Two coins. Now take a paper and fold it in half. Then fold again. Open it. Four parts. Each is a fourth. Color one part. You just made a fraction, the way the Word made them, by dividing a whole into equal parts.', inApp: 'With ten coins, show a tenth and a fifth. Fold a paper into halves and fourths and color one fourth. Then say what a double portion means.', benefits: ['The tenth from the tithe; the fifth from restitution and from Joseph; the half from Zacchaeus.', 'Finding a part by sharing: a tenth of one hundred is ten, a fifth of ten is two.', 'The double portion: two parts against one.', 'An omer is a tenth of an ephah: fractions inside a real measure, and five tenths is a half.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'A tenth of one hundred bags is how many bags?', options: ['Ten', 'One', 'Twenty'], answer: 0, explain: 'Share one hundred into ten equal parts: ten each. 1/10 of 100 is 10.' }, { q: 'A man took ten coins and must add a fifth. How many does he give back?', options: ['Ten', 'Twelve', 'Fifteen'], answer: 1, explain: 'A fifth of ten is two. Ten plus two is twelve.' }, { q: 'Half of forty coins is how many?', options: ['Twenty', 'Ten', 'Eighty'], answer: 0, explain: 'Share forty into two equal parts: twenty each.' }, { q: 'How many omers make one ephah?', options: ['Five', 'Ten', 'Two'], answer: 1, explain: 'Exodus 16:36: an omer is the tenth part of an ephah, so ten omers make one.' }, { q: 'A double portion means how many parts?', options: ['Two', 'One', 'Half'], answer: 0, explain: 'Double means two parts where another gets one.' }, { q: 'Five tenths is the same as what?', options: ['A fifth', 'A half', 'A tenth'], answer: 1, explain: 'Five out of ten equal parts is half of the whole.' }] }, facilitator: { talkingPoints: ['Leviticus 27:30: the tenth; find it by sharing into ten.', 'Leviticus 6:5; Genesis 41:34: the fifth, in restitution and in Joseph’s storehouse.', 'Luke 19:8: the half, and fourfold.', 'Deuteronomy 21:17: the double portion.', 'Exodus 16:36: omer and ephah; five tenths is a half.'], howToRun: 'No grown-up is needed. If one is near: use ten coins for tenths and fifths, fold paper for halves and fourths, and write each fraction as you make it. Redo the check as a game (about 20 minutes).', discussionPrompts: ['How do you find a tenth of a number?', 'Why did the Word add a fifth when something was given back?', 'What is half of the number of people in your house?'] } },
  { id: 'mat5-measure-cubits-spans-ephahs-and-just-weights', title: 'Measure — Cubits, Spans, Ephahs and a Just Weight', bigIdea: 'THE ARK WAS THREE HUNDRED CUBITS BY FIFTY BY THIRTY, GOLIATH WAS SIX CUBITS AND A SPAN, THE ARK OF THE COVENANT WAS TWO AND A HALF CUBITS LONG, AND YAHWEH COMMANDS A JUST WEIGHT: MEASURING IS OBEDIENCE', anchor: { ref: 'Genesis 6:15; 1 Samuel 17:4; Exodus 25:10; Leviticus 19:36', theme: 'KJV: "Just balances, just weights, a just ephah, and a just hin, shall ye have: I am the LORD your God, which brought you out of the land of Egypt." (Leviticus 19:36)' }, lesson: 'Measuring is saying how long, how heavy, or how much. The Word measures with real units. The first unit is the cubit. A cubit is from your elbow to the tip of your longest finger. Hold out your arm. That is about one cubit. A grown man\'s cubit is about half a meter, or about eighteen inches. A span is smaller. Spread your hand wide. From your thumb tip to your little finger tip is a span. Two spans make about one cubit. Now measure with the Word. Noah\'s ark. "And this is the fashion which thou shalt make it of: The length of the ark shall be three hundred cubits, the breadth of it fifty cubits, and the height of it thirty cubits." (Genesis 6:15) Three hundred cubits long. Fifty cubits wide. Thirty cubits high. That is a big boat. Three hundred cubits is about one hundred fifty meters. Longer than a football field. Compare the sides. Length three hundred, width fifty. Three hundred shared by fifty is six. The ark was six times as long as it was wide. Now Goliath. "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span." (1 Samuel 17:4) Six cubits and a span. Six cubits plus one span. Six cubits is about three meters. A span adds a little more. He was much taller than a door. Now a small holy box. The ark of the covenant. "And they shall make an ark of shittim wood: two cubits and a half shall be the length thereof, and a cubit and a half the breadth thereof, and a cubit and a half the height thereof." (Exodus 25:10) Two cubits and a half long. That is two and a half cubits. Write it. 2 1/2. A cubit and a half wide. 1 1/2. A cubit and a half high. 1 1/2. See the halves? Measuring uses fractions. Now measure grain. The Word uses the ephah and the omer. "Now an omer is the tenth part of an ephah." (Exodus 16:36) Ten omers in an ephah. And for liquid, the hin. "Just balances, just weights, a just ephah, and a just hin, shall ye have: I am the LORD your God, which brought you out of the land of Egypt." (Leviticus 19:36) A just ephah. A just hin. Just means true. Honest. The same size every time. Now the most important measuring rule of all. Look at that same verse again. Just balances, just weights. A balance is a scale. Put the thing on one side and a weight on the other. If the weight is true, the deal is true. Yahweh cares about this. "A false balance is abomination to the LORD: but a just weight is his delight." (Proverbs 11:1) A false weight is a lie you tell with a thing. A true weight makes Him glad. So when you measure, measure true. Try it. Measure your table in cubits with your own arm. Write the number. Now measure it with a ruler. Write that too. Are they the same? Your cubit is smaller than a grown up\'s cubit. That is why the world agreed on rulers with the same marks. But the idea started here. A unit, used the same way every time, so the measure is just.', inApp: 'Measure your table with your arm in cubits and with a ruler. Write both numbers. Then say the three measurements of Noah’s ark from memory.', benefits: ['The cubit and the span, from the learner’s own arm and hand.', 'Noah’s ark: three hundred by fifty by thirty, and length six times width.', 'Goliath and the ark of the covenant: whole cubits and half cubits.', 'Ephah, omer and hin: units for grain and liquid, ten omers to the ephah.', 'A just weight: measuring true is a command, not a tip.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'A cubit is measured from where to where?', options: ['Knee to foot', 'Elbow to fingertip', 'Shoulder to wrist'], answer: 1, explain: 'A cubit is from the elbow to the tip of the longest finger.' }, { q: 'How long was Noah’s ark?', options: ['Three hundred cubits', 'Fifty cubits', 'Thirty cubits'], answer: 0, explain: 'Genesis 6:15: three hundred cubits long, fifty wide, thirty high.' }, { q: 'The ark was how many times as long as it was wide?', options: ['Six', 'Ten', 'Three'], answer: 0, explain: '300 shared by 50 is 6.' }, { q: 'How long was the ark of the covenant?', options: ['Two and a half cubits', 'Ten cubits', 'Six cubits and a span'], answer: 0, explain: 'Exodus 25:10: two cubits and a half. Six cubits and a span was Goliath.' }, { q: 'How many omers make an ephah?', options: ['Two', 'Ten', 'Fifty'], answer: 1, explain: 'An omer is the tenth part of an ephah, so ten omers.' }, { q: 'What does a just weight mean?', options: ['A heavy weight', 'A true and honest weight', 'A gold weight'], answer: 1, explain: 'Just means true: the same every time, so no one is cheated. Proverbs 11:1 says a false balance is an abomination to Him.' }] }, facilitator: { talkingPoints: ['Genesis 6:15: 300 by 50 by 30; length is six times width.', '1 Samuel 17:4: six cubits and a span.', 'Exodus 25:10: two and a half by one and a half by one and a half; halves inside measure.', 'Exodus 16:36; Leviticus 19:36: omer, ephah, hin; just balances.', 'Proverbs 11:1: measure true.'], howToRun: 'No grown-up is needed. If one is near: measure the same table with the learner’s arm, the grown-up’s arm, and a ruler; talk about why the numbers differ and why a shared unit matters. Redo the check as a game (about 20 minutes).', discussionPrompts: ['Why is your cubit different from a grown up’s cubit?', 'How many cubits long is your bed?', 'Why does Yahweh care about a true weight?'] } },
  { id: 'mat6-shapes-the-molten-sea-the-foursquare-altar-and-the-bow', title: 'Shapes — the Round Sea, the Foursquare Altar and the Bow in the Cloud', bigIdea: 'SOLOMON’S SEA WAS TEN CUBITS ACROSS AND THIRTY ROUND ABOUT, THE ALTAR WAS FOURSQUARE, THE HOLY CITY IS A CUBE, AND THE RAINBOW IS AN ARC: CIRCLES, SQUARES AND CUBES ARE IN THE WORD, MEASURED', anchor: { ref: '1 Kings 7:23; Exodus 27:1; Revelation 21:16; Genesis 9:13', theme: 'KJV: "And he made a molten sea, ten cubits from the one brim to the other: it was round all about, and his height was five cubits: and a line of thirty cubits did compass it round about." (1 Kings 7:23)' }, lesson: 'A shape is the form of a thing. The Word describes shapes and measures them. Start with the circle. Solomon made a huge round basin for the temple. "And he made a molten sea, ten cubits from the one brim to the other: it was round all about, and his height was five cubits: and a line of thirty cubits did compass it round about." (1 Kings 7:23) Round all about. Ten cubits from one brim to the other. That is the distance across. Math calls it the diameter. Thirty cubits round about. That is the distance around. Math calls it the circumference. Now compare them. Thirty round about, ten across. Thirty shared by ten is three. The distance around was about three times the distance across. Here is something honest to say. If you measure any circle exactly, the distance around is a little more than three times the distance across. It is about three and one seventh. The Word gives the sea\'s measures in whole cubits, ten and thirty, the way a builder states a size. It is not teaching a formula. It is describing a real basin. The same passage says the brim was as thick as a hand. "And it was an hand breadth thick, and the brim thereof was wrought like the brim of a cup, with flowers of lilies: it contained two thousand baths." (1 Kings 7:26) A handbreadth thick. So the inside was a little smaller than the outside. Math learned the exact number by measuring many circles. The Word gave the builder\'s numbers. Both are true. Now the square. The altar. "And thou shalt make an altar of shittim wood, five cubits long, and five cubits broad; the altar shall be foursquare: and the height thereof shall be three cubits." (Exodus 27:1) Five cubits long, five cubits broad. The same on each side. Foursquare means four equal sides with square corners. Three cubits high. Count its sides. Four. Count its corners. Four. If you walk around it, you walk five plus five plus five plus five. Twenty cubits. That is its distance around. Now the cube. A cube is a box with every side the same. The holy city is described that way. "And the city lieth foursquare, and the length is as large as the breadth: and he measured the city with the reed, twelve thousand furlongs. The length and the breadth and the height of it are equal." (Revelation 21:16) The length, the breadth and the height are equal. That is a cube. Count the faces of a cube. Six. Count the corners. Eight. Count the edges. Twelve. Look at a dice. Six faces, eight corners, twelve edges. Now the arc. After the flood Yahweh set a sign in the sky. "I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth." (Genesis 9:13) A bow. A rainbow is a part of a circle. An arc. When you see one, you see a piece of a big circle, with the ground cutting off the rest. Now the wheel. Ezekiel saw wheels. "The appearance of the wheels and their work was like unto the colour of a beryl: and they four had one likeness: and their appearance and their work was as it were a wheel in the middle of a wheel." (Ezekiel 1:16) A wheel in the middle of a wheel. Two circles, one inside the other. Try it. Find a round thing, like a can. Wrap a string around it. Cut the string. That is the distance around. Now lay the string across the can, over and over. How many times does it fit? About three, with a little left over. You just measured what Solomon\'s builders measured. Then draw a square with four equal sides and a cube from a box. Count the faces, corners and edges.', inApp: 'Wrap a string around a can, then lay it across the can and count how many times it fits. Draw a foursquare altar with sides of 5 and find its distance around.', benefits: ['The circle: distance across and distance around, from Solomon’s sea, with the honest line between a builder’s measure and a formula.', 'The square: four equal sides, four corners, distance around by adding.', 'The cube: six faces, eight corners, twelve edges, from the holy city.', 'The arc and the wheel: the bow in the cloud and Ezekiel’s wheels.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'Solomon’s sea was ten cubits across and thirty round about. Thirty shared by ten is what?', options: ['Three', 'Ten', 'Forty'], answer: 0, explain: 'The distance around was about three times the distance across. Exact circles give a little more than three.' }, { q: 'What does foursquare mean?', options: ['Four equal sides with square corners', 'Four circles', 'A shape with no corners'], answer: 0, explain: 'The altar was five by five: four equal sides and square corners.' }, { q: 'Walking around a square with sides of five cubits is how far?', options: ['Ten cubits', 'Twenty cubits', 'Twenty five cubits'], answer: 1, explain: 'Add the four equal sides: 5 + 5 + 5 + 5 = 20 cubits around.' }, { q: 'How many faces does a cube have?', options: ['Four', 'Six', 'Eight'], answer: 1, explain: 'Six faces, eight corners, twelve edges. Look at a dice.' }, { q: 'A rainbow is what part of a circle?', options: ['The whole circle', 'An arc', 'A square'], answer: 1, explain: 'An arc is a piece of a circle. The ground cuts the rest off.' }, { q: 'Does the Word teach a formula for circles in 1 Kings 7:23?', options: ['Yes, it gives the exact number', 'No, it gives a builder’s measure in whole cubits', 'It says nothing about circles'], answer: 1, explain: 'It describes a real basin, ten across and thirty about, in whole cubits. Mathematics learned the exact ratio by measuring many circles. Both are true.' }] }, facilitator: { talkingPoints: ['1 Kings 7:23, 26: ten across, thirty about, a handbreadth thick; the honest line about the ratio.', 'Exodus 27:1: foursquare; distance around by adding four sides.', 'Revelation 21:16: the cube; faces, corners, edges.', 'Genesis 9:13; Ezekiel 1:16: the arc and the wheel within a wheel.'], howToRun: 'No grown-up is needed. If one is near: do the string-around-a-can measure together and count how many times the string fits across; then count faces, corners and edges on a box. Redo the check as a game (about 25 minutes).', discussionPrompts: ['What did the string show you about circles?', 'Why is it honest to say the sea’s numbers are a builder’s measure?', 'Find three squares and one circle in your room.'] } },
  { id: 'mat7-time-and-cycles-sevens-forty-days-and-the-fiftieth-year', title: 'Time and Cycles — Sevens, Forty Days, Seventy Years and the Fiftieth Year', bigIdea: 'SEVEN DAYS MAKE A WEEK, SEVEN YEARS MAKE A RELEASE, SEVEN SEVENS MAKE FORTY-NINE AND THE NEXT YEAR IS THE JUBILEE, AND DANIEL COUNTED SEVENTY YEARS FROM THE BOOKS: THE WORD KEEPS TIME IN PATTERNS', anchor: { ref: 'Genesis 2:2; Deuteronomy 15:1; Leviticus 25:8; Leviticus 25:10', theme: 'KJV: "And thou shalt number seven sabbaths of years unto thee, seven times seven years; and the space of the seven sabbaths of years shall be unto thee forty and nine years." (Leviticus 25:8)' }, lesson: 'Time moves in patterns. The Word set the first pattern. "And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and years:" (Genesis 1:14) The lights in the sky mark days, seasons and years. Then the week. "And on the seventh day God ended his work which he had made; and he rested on the seventh day from all his work which he had made." (Genesis 2:2) Six days of work. One day of rest. Seven days. Count a week on your fingers. One, two, three, four, five, six, seven. Then it starts again. That is a cycle. Two weeks is fourteen days. 2 x 7 = 14. Four weeks is twenty eight days. 4 x 7 = 28. Now a bigger seven. "At the end of every seven years thou shalt make a release." (Deuteronomy 15:1) Every seven years, a release. Debts were let go. Count it. Year one, two, three, four, five, six, seven. Release. Then start again. Fourteen years is two releases. Twenty one years is three. Now the biggest seven pattern. "And thou shalt number seven sabbaths of years unto thee, seven times seven years; and the space of the seven sabbaths of years shall be unto thee forty and nine years." (Leviticus 25:8) Seven times seven years. Seven sevens. Seven, fourteen, twenty one, twenty eight, thirty five, forty two, forty nine. 7 x 7 = 49. Forty nine years. Then the next year is special. "And ye shall hallow the fiftieth year, and proclaim liberty throughout all the land unto all the inhabitants thereof: it shall be a jubile unto you; and ye shall return every man unto his possession, and ye shall return every man unto his family." (Leviticus 25:10) The fiftieth year. Forty nine plus one. 49 + 1 = 50. The jubilee. Everyone went home to their land. So a jubilee cycle is fifty years. How many jubilees in one hundred years? Two. 100 shared by 50 is 2. Now forty. Forty comes up a lot. "And the rain was upon the earth forty days and forty nights." (Genesis 7:12) Forty days of rain. That is how many weeks? Forty shared by seven is five, with five left over. Five weeks and five days. Now seventy. Jeremiah said the captivity would last seventy years. "And this whole land shall be a desolation, and an astonishment; and these nations shall serve the king of Babylon seventy years." (Jeremiah 25:11) And Daniel read it and counted. "In the first year of his reign I Daniel understood by books the number of the years, whereof the word of the LORD came to Jeremiah the prophet, that he would accomplish seventy years in the desolations of Jerusalem." (Daniel 9:2) Daniel understood by books. He read the number and did the math. If the captivity began in a year we call year zero, it would end in year seventy. Daniel knew where he was in the count. That is what a cycle lets you do. You can find your place. Try it. Make a calendar of one week. Mark the rest day. Then count how many weeks until your birthday. Multiply the weeks by seven to get days. Now count by sevens to forty nine, then add one. Say jubilee. Then find how many sevens are in forty, and how many are left over.', inApp: 'Make a one-week calendar and mark the rest day. Count by sevens to 49 and add one for the jubilee. Then find how many weeks and days are in forty days.', benefits: ['The week as the first cycle, and multiplying weeks by seven.', 'The seven-year release: a cycle of years.', 'Seven sevens are forty nine; the fiftieth year is the jubilee.', 'Forty days as five weeks and five days: division with a remainder.', 'Daniel counted seventy years from the books: reading a number and finding your place.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'How many days are in four weeks?', options: ['Twenty one', 'Twenty eight', 'Thirty'], answer: 1, explain: 'Four weeks of seven days: 4 x 7 = 28 days.' }, { q: 'Seven sevens is how many years?', options: ['Fourteen', 'Forty nine', 'Seventy'], answer: 1, explain: 'Seven times seven years: 7 x 7 = 49. Leviticus 25:8 counts it.' }, { q: 'The jubilee is which year?', options: ['The seventh', 'The fiftieth', 'The hundredth'], answer: 1, explain: 'After forty nine years, the fiftieth year is the jubilee. 49 + 1 = 50.' }, { q: 'Forty days is how many weeks and days?', options: ['Five weeks and five days', 'Four weeks', 'Six weeks and two days'], answer: 0, explain: 'Forty shared by seven is five with five left over.' }, { q: 'How many jubilee cycles are in one hundred years?', options: ['One', 'Two', 'Four'], answer: 1, explain: 'One hundred shared by fifty is two: 100 shared by 50 is 2.' }, { q: 'How did Daniel know the captivity would last seventy years?', options: ['He guessed', 'He read it in the books and counted', 'A king told him'], answer: 1, explain: 'Daniel 9:2: he understood by books the number of the years.' }] }, facilitator: { talkingPoints: ['Genesis 1:14; 2:2: the lights mark time; the week is the first cycle.', 'Deuteronomy 15:1: release every seven years.', 'Leviticus 25:8, 10: 7 x 7 = 49; the fiftieth is the jubilee.', 'Genesis 7:12: forty days is five weeks and five days.', 'Jeremiah 25:11; Daniel 9:2: seventy years, counted from the books.'], howToRun: 'No grown-up is needed. If one is near: draw the week, count by sevens together, and work forty divided by seven with counters to show the remainder. Redo the check as a game (about 20 minutes).', discussionPrompts: ['What is a cycle?', 'Why did Yahweh put a rest into every seven?', 'How did counting help Daniel know where he was?'] } },
  { id: 'mat8-quality-and-quantity-gideons-three-hundred-and-the-widows-two-mites', title: 'Quality and Quantity — Gideon’s Three Hundred, Daniel’s Ten Days and the Widow’s Two Mites', bigIdea: 'A COUNT TELLS HOW MANY AND A LOOK TELLS WHAT KIND: GIDEON’S MEN WERE CHOSEN BY HOW THEY DRANK, DANIEL RAN A TEN-DAY TEST AND COMPARED, AND TWO MITES WERE MORE THAN ALL THE REST, SO MATHEMATICS NEEDS BOTH', anchor: { ref: 'Judges 7:5; Judges 7:7; Daniel 1:12; Daniel 1:15; Mark 12:43', theme: 'KJV: "And he called unto him his disciples, and saith unto them, Verily I say unto you, That this poor widow hath cast more in, than all they which have cast into the treasury:" (Mark 12:43)' }, lesson: 'There are two ways to know a thing. You can count it. That is quantity. How many. How much. Or you can look at what kind of thing it is. That is quality. What sort. What it is like. Good math uses both. Start with Gideon. Yahweh had already made the army small. Ten thousand men were left. Then He gave a test that was not about counting. "So he brought down the people unto the water: and the LORD said unto Gideon, Every one that lappeth of the water with his tongue, as a dog lappeth, him shalt thou set by himself; likewise every one that boweth down upon his knees to drink." (Judges 7:5) Watch how they drink. Some lapped like a dog. Some got down on their knees. That is quality. Not how many, but how. Then came the count. "And the number of them that lapped, putting their hand to their mouth, were three hundred men: but all the rest of the people bowed down upon their knees to drink water." (Judges 7:6) Three hundred lapped. That is quantity. Then the choice. "And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place." (Judges 7:7) Three hundred, chosen by how they drank. See both together. A quality, the way of drinking, sorted the men. A quantity, three hundred, counted the group. Now Daniel. Daniel did not want to eat the king\'s rich food. So he asked for a test. "Prove thy servants, I beseech thee, ten days; and let them give us pulse to eat, and water to drink." (Daniel 1:12) Ten days. That is a quantity. A set time to measure. Then compare. "Then let our countenances be looked upon before thee, and the countenance of the children that eat of the portion of the king’s meat: and as thou seest, deal with thy servants." (Daniel 1:13) Look at our faces and their faces. That is quality. What do we look like? After ten days, the result. "And at the end of ten days their countenances appeared fairer and fatter in flesh than all the children which did eat the portion of the king’s meat." (Daniel 1:15) Fairer and fatter. Daniel ran a fair test. Same time for both groups. Then he looked and compared. That is how a scientist tests something today. A set count, then a careful look. Now the widow. Jesus watched people give money at the temple. Rich people gave a lot. A poor widow gave two mites. Two tiny coins. "And there came a certain poor widow, and she threw in two mites, which make a farthing." (Mark 12:42) Count it. Two. The smallest amount that day. Then Jesus said something surprising. "And he called unto him his disciples, and saith unto them, Verily I say unto you, That this poor widow hath cast more in, than all they which have cast into the treasury:" (Mark 12:43) More than all. How? By quantity, two mites is the least. By quality, it was everything she had. The others gave from their extra. She gave all. Jesus measured what kind of gift it was, not only how big. So the biggest number is not always the most. Now build with both. Jesus said to count before you build. "For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?" (Luke 14:28) Count the cost. That is quantity. Do I have enough stones? And a king going to war counts too. "Or what king, going to make war against another king, sitteth not down first, and consulteth whether he be able with ten thousand to meet him that cometh against him with twenty thousand?" (Luke 14:31) Ten thousand against twenty thousand. Two to one. Write it. 2 x 10,000 = 20,000. Quantity tells him the odds. Then he must judge what kind of army he has. That is quality. Both together make a wise choice. Here is the man who did both best. Bezaleel built the tabernacle. "And I have filled him with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship," (Exodus 31:3) Wisdom, understanding, knowledge, and all kinds of workmanship. Counting cubits is knowledge. Knowing what wood to use is understanding. Knowing why it is built is wisdom. He had all three from Yahweh\'s Spirit. And he taught it to others. "And he hath put in his heart that he may teach, both he, and Aholiab, the son of Ahisamach, of the tribe of Dan." (Exodus 35:34) Try it. Count the shoes in your house. That is quantity. Now sort them. Which are for rain, which for church, which for running? That is quality. Then run a Daniel test. Water two plants the same. Give one sunlight and one none. Count ten days. Then look. Which is fairer? Write what you counted and what you saw. That is both kinds of knowing.', inApp: 'Count the shoes in your house, then sort them by what they are for. Start a ten-day plant test with one in the sun and one in the shade, and write the count and the look each day.', benefits: ['Quantity and quality named plainly: how many, and what kind.', 'Gideon: sorted by a quality, counted to three hundred.', 'Daniel: a ten-day test with a fair comparison, the shape of a real experiment.', 'The widow: two mites, the least by count, the most by kind.', 'Counting the cost and the two-to-one king: numbers and judgment together.', 'Bezaleel: knowledge, understanding, wisdom and workmanship, given and then taught.'], levels: {  }, readOptionsAloud: true, quiz: { questions: [{ q: 'Which is quantity?', options: ['How many', 'What kind', 'What color'], answer: 0, explain: 'Quantity is how many or how much. Quality is what kind.' }, { q: 'How were Gideon’s three hundred chosen?', options: ['By age', 'By how they drank', 'By height'], answer: 1, explain: 'Judges 7:5-7: the ones who lapped the water were chosen, three hundred of them.' }, { q: 'How long was Daniel’s test?', options: ['Ten days', 'Seven days', 'A year'], answer: 0, explain: 'Daniel 1:12: prove thy servants ten days.' }, { q: 'What did Daniel do at the end of the ten days?', options: ['Counted the food', 'Compared the faces', 'Went home'], answer: 1, explain: 'Daniel 1:13, 15: their faces were looked at and compared, and they were fairer and fatter.' }, { q: 'Why was the widow’s two mites more than all?', options: ['Two is a big number', 'She gave all she had', 'The coins were gold'], answer: 1, explain: 'By count it was the least; by kind it was everything she had. Mark 12:43-44.' }, { q: 'Which is a quality test?', options: ['Counting the shoes', 'Sorting the shoes by what they are for', 'Weighing the shoes'], answer: 1, explain: 'Sorting by kind is quality. Counting and weighing are quantity.' }, { q: 'What three things did Bezaleel have from the Spirit?', options: ['Gold, silver, brass', 'Wisdom, understanding, knowledge', 'Wood, stone, cloth'], answer: 1, explain: 'Exodus 31:3: wisdom, understanding, knowledge, and all manner of workmanship.' }] }, facilitator: { talkingPoints: ['Judges 7:5-7: a quality sorts, a quantity counts.', 'Daniel 1:12-15: a set count of days, a fair comparison, a result.', 'Mark 12:42-44: the least by count, the most by kind.', 'Luke 14:28, 31: count the cost; two to one.', 'Exodus 31:3; 35:34: knowledge, understanding, wisdom, workmanship, and teaching it on.'], howToRun: 'No grown-up is needed. If one is near: do the shoe count and sort together, then set up the two-plant test and keep a simple chart with a count column and a look column. Redo the check as a game (about 25 minutes, plus the ten days of the plant test).', discussionPrompts: ['Name one thing you can count and one thing you can only look at.', 'Why did Daniel set the same ten days for both groups?', 'When was the smallest number the most, in your own life?'] } },
];

export const MATHEMATICS_META = {
  key: 'mathematics',
  title: 'Mathematics — Counting, Measure and Reason from the Word',
  audience: 'school-age learners, about 6 to 11, and anyone starting mathematics again',
  tagline: 'Every number, every measure, every shape here is one the Word records — the working shown, the check redoable.',
  format: 'Self-paced · read aloud by the app · worked examples on the page · redo any check as a game',
  cadenceDays: 2,
  programLevel: 'Elementary',
  weeks: MATHEMATICS_MODULES.length,
  // Word-first lead (DR-0127): the frame a learner meets before any number.
  wordFirst: {
    ref: 'Psalms 147:4-5; Isaiah 40:12',
    frame: 'He tells the number of the stars and calls them all by their names; His understanding is infinite; He measured the waters in the hollow of His hand and weighed the mountains in scales. Mathematics is learning to count, measure and reason in a world He counted, measured and reasoned first — so every lesson here starts from a number or a measure the Word itself records.',
  },
};

export const MATHEMATICS_SESSION_FLOW = [
  { minutes: 2, name: 'The verse, read aloud' },
  { minutes: 8, name: 'The lesson, with the working shown' },
  { minutes: 6, name: 'Try it with your hands' },
  { minutes: 4, name: 'The check — a game you can redo' },
];
export const MATHEMATICS_SESSION_MINUTES = MATHEMATICS_SESSION_FLOW.reduce((t, s) => t + s.minutes, 0);

export const MATHEMATICS_INTEREST_TAG = '[Mathematics interest]';
export const MATHEMATICS_HELPER_TAG = '[Mathematics helper]';

export function resolveMathematicsCohort(localCohort = null) {
  return resolveCohortGeneric(localCohort, MATHEMATICS_CONFIRMED_COHORT, MATHEMATICS_PROPOSED_COHORT_START);
}

// Self-paced: one row per lesson, no painted date.
export function buildMathematicsSchedule() {
  return MATHEMATICS_MODULES.map((m, i) => ({ ...m, week: i + 1, date: null, weekday: null }));
}

export function mathematicsProgressSummary(progress = {}) {
  return progressSummaryFor(MATHEMATICS_MODULES, progress);
}

export function exportMathematicsCurriculumMarkdown() {
  return exportCurriculumMarkdownFor(
    { meta: MATHEMATICS_META, sessionFlow: MATHEMATICS_SESSION_FLOW, modules: MATHEMATICS_MODULES },
    null,
  );
}

// Ari for mathematics: show the working, every number from the Word, never a
// guessed figure, and the honest line between what the Word records and what
// mathematics adds beside it.
export const MATHEMATICS_TUTOR_META = {
  title: MATHEMATICS_META.title,
  intro: 'You are Ari, a patient mathematics helper for a school-age learner (about 6 to 11) working through Word-based mathematics in "Mathematics — Counting, Measure and Reason from the Word."',
  posture: 'Show the working, one step per line, in short sentences. Every number you teach with comes from this lesson or from a Bible verse quoted in it; never invent a figure and never round a Bible number to something it does not say. When mathematics adds something beside the Word (a formula, a decimal, a name like ratio), say plainly that the Word records the measure and mathematics gives it that name. If the learner is wrong, say the right answer gently, show why, and let them try again — the check is a game they can redo. Say Yahweh for the Father, and Jesus for the Son. Keep every answer under five sentences.',
};
